import { Controller, Get, Post, Param } from "@nestjs/common"

@Controller("cats")                 // prefiks: bu klassdagi hamma yo'llar /cats bilan boshlanadi
export class CatsController {
    @Get()                          // GET /cats
    findAll() {
        return ["Mosh", "Barsik"]   // massiv → JSON, status 200
    }

    @Get(":id")                     // GET /cats/7 — :id dinamik segment
    findOne(@Param("id") id: string) {
        return { id }               // {"id":"7"}
    }

    @Post()                         // POST /cats — status 201
    create() {
        return "Yaratildi"
    }
}

@Controller()                      @Get("health")           → GET /health
@Controller("cats")                @Get()                   → GET /cats
@Controller("cats")                @Get(":id")              → GET /cats/:id
@Controller("admin/users")         @Get("count")            → GET /admin/users/count
@Controller("users/:userId")       @Get("orders/:orderId")  → GET /users/:userId/orders/:orderId
@Controller(["products", "mahsulotlar"])  @Get()          → GET /products  va  GET /mahsulotlar
// + app.setGlobalPrefix("api")                             → GET /api/cats ...

@Controller("users/:userId/orders")
export class UserOrdersController {
    @Get()                                   // GET /users/7/orders
    all(@Param("userId") userId: string) { return { userId } }

    @Get(":orderId")                         // GET /users/7/orders/101
    one(@Param() p: { userId: string; orderId: string }) { return p }   // {"userId":"7","orderId":"101"}
}

// ✘ noto'g'ri tartib — /users/me doim byId'ga tushadi
@Get(":id") byId(@Param("id") id: string) {}
@Get("me")  me() {}                 // o'lik kod

// ✔ to'g'ri: statik oldin, dinamik keyin, wildcard oxirida
@Get("me")      me() {}
@Get(":id")     byId(@Param("id") id: string) {}
@Get("*splat")  fallback() {}

// main.ts — global prefiks va istisnolar
app.setGlobalPrefix("api", {
    exclude: ["health", { path: "metrics", method: RequestMethod.GET }],
})

// app.module.ts — modul prefiksi
RouterModule.register([
    { path: "admin", module: AdminModule, children: [{ path: "reports", module: ReportsModule }] },
])
// AdminModule controller'lari → /api/admin/...,  ReportsModule → /api/admin/reports/...

