import { Controller, Get, Module } from "@nestjs/common"
import { request } from "node:http"

@Controller({ host: "admin.localhost", path: "dashboard" })
class AdminDashboardController {
    @Get() get() { return { panel: "admin", host: "admin.localhost" } }
}

@Controller("dashboard")
class PublicDashboardController {
    @Get() get() { return { panel: "public" } }
}

// host'li controller oldin — mos kelmasa navbat host'sizga o'tadi
@Module({ controllers: [AdminDashboardController, PublicDashboardController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const { port } = new URL(await http.app.getUrl())
    for (const host of ["admin.localhost", "shop.localhost"]) {      // fetch Host'ni o'zgartirmaydi — node:http
        const body = await new Promise<string>((res, rej) => {
            request({ host: "127.0.0.1", port, path: "/dashboard", headers: { Host: host } }, r => {
                let d = ""; r.on("data", c => (d += c)); r.on("end", () => res(`${r.statusCode} ${d}`))
            }).on("error", rej).end()
        })
        console.log(`Host: ${host} → ${body}`)
    }
    await http.close()
}
main()

import { Controller, Get, Head, Module, Options, Param, Res } from "@nestjs/common"
import type { Response } from "express"

@Controller("files")
class FilesController {
    @Head(":name")                                   // HEAD /files/x — tanasiz, faqat sarlavhalar
    head(@Param("name") name: string, @Res({ passthrough: true }) res: Response) {
        res.setHeader("X-File-Size", String(name.length * 1024))
    }

    @Options()                                       // OPTIONS /files
    options(@Res({ passthrough: true }) res: Response) {
        res.setHeader("Allow", "GET, HEAD, OPTIONS")
    }

    @Get(":name")
    get(@Param("name") name: string) { return { name } }
}

@Module({ controllers: [FilesController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const base = await http.app.getUrl()
    const head = await fetch(base + "/files/report.pdf", { method: "HEAD" })
    console.log("HEAD /files/report.pdf →", head.status, "| tana:", (await head.text()).length, "bayt | X-File-Size:", head.headers.get("x-file-size"))
    const opts = await fetch(base + "/files", { method: "OPTIONS" })
    console.log("OPTIONS /files →", opts.status, "| Allow:", opts.headers.get("allow"))
    await http.get("/files/report.pdf")
    await http.close()
}
main()

