import { Body, Controller, Get, Headers, Param, Post, Query } from "@nestjs/common"

class CreateUserDto {           // body shakli — klass (interface emas!)
    name: string
    email: string
}

@Controller("users")
export class UsersController {
    @Get(":id")                                                     // GET /users/7?fields=name
    findOne(@Param("id") id: string, @Query("fields") fields?: string) {
        return { id, fields }                                       // {"id":"7","fields":"name"}
    }

    @Post()                                                         // POST /users  {"name":"Aziz","email":"a@mail.uz"}
    create(@Body() dto: CreateUserDto, @Headers("x-request-id") reqId?: string) {
        return { ...dto, reqId }
    }
}

@Get(":id")
one(@Param("id", ParseIntPipe) id: number) {      // "41" → 41;  "abc" → 400 Bad Request
    return { id, next: id + 1 }
}

@Get(":year/:month")
archive(@Param() p: { year: string; month: string }) { return p }   // {"year":"2026","month":"09"}

@Get()
list(
    @Query("page", new DefaultValuePipe(1), ParseIntPipe) page: number,   // ?page=3 → 3, yo'q bo'lsa 1
    @Query("tag") tag?: string | string[],                                 // ?tag=a&tag=b → ["a","b"]
    @Query("q") q = "",                                                    // TypeScript standart qiymati
) {
    return { page, tags: [tag ?? []].flat(), q }
}

class CreateOrderDto {
    @IsInt() @Min(1) productId: number      // class-validator dekoratorlari — Pipes bo'limi
    @IsInt() @Min(1) qty: number
    @IsOptional() @IsString() note?: string
}

@Post()
create(@Body() dto: CreateOrderDto) { return { ...dto, total: dto.qty * 25000 } }

@Post("quick")
quick(@Body("productId", ParseIntPipe) productId: number) { return { productId } }   // faqat bitta maydon

@Get("me")
me(
    @Headers("authorization") auth: string | undefined,   // "Bearer abc123" yoki undefined
    @Headers() all: Record<string, string>,               // hamma sarlavhalar, kalitlar kichik harfda
    @Ip() ip: string,                                     // "127.0.0.1" yoki "::ffff:127.0.0.1"
    @Session() session: Record<string, any>,              // express-session ulangan bo'lsa
) {
    session.visits = (session.visits ?? 0) + 1
    return { token: auth?.slice(7), lang: all["accept-language"], ip, visits: session.visits }
}

// ✘ satrni son bilan solishtirish — doim false
@Get(":id") one(@Param("id") id: number) { return id === 7 }

// ✔ pipe qiymatni haqiqatan songa aylantiradi
@Get(":id") one(@Param("id", ParseIntPipe) id: number) { return id === 7 }

// ✘ interface — ishlash paytida yo'q, ValidationPipe tekshira olmaydi
// interface CreateDto { name: string }
// ✔ klass + dekoratorlar
class CreateDto { @IsString() @MinLength(2) name: string }

