import { Controller, Get, Module, Query } from "@nestjs/common"

const products = [
    { id: 1, name: "Noutbuk", category: "tech", price: 9000 },
    { id: 2, name: "Telefon", category: "tech", price: 4500 },
    { id: 3, name: "Ko'ylak", category: "clothes", price: 250 },
    { id: 4, name: "Planshet", category: "tech", price: 3000 },
]

@Controller("products")
class ProductsController {
    @Get()
    find(
        @Query("category") category?: string,
        @Query("maxPrice") maxPrice?: string,
        @Query("page") page = "1",
        @Query("limit") limit = "2",
    ) {
        let result = products
        if (category) result = result.filter(p => p.category === category)
        if (maxPrice) result = result.filter(p => p.price <= Number(maxPrice))
        const start = (Number(page) - 1) * Number(limit)
        return { total: result.length, items: result.slice(start, start + Number(limit)).map(p => p.name) }
    }
}

@Module({ controllers: [ProductsController] })
class AppModule {}

