import { Body, Controller, Module, Post, RawBodyRequest, Req } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import type { Request } from "express"
import { createHmac } from "node:crypto"

@Controller("webhook")
class WebhookController {
    @Post()
    receive(@Req() req: RawBodyRequest<Request>, @Body() body: { event: string }) {
        const raw = req.rawBody!                                             // Buffer — o'zgartirilmagan asl JSON
        const signature = createHmac("sha256", "secret").update(raw).digest("hex").slice(0, 12)
        return { event: body.event, bytes: raw.length, signature }
    }
}

@Module({ controllers: [WebhookController] })
class AppModule {}

async function main() {
    const app = await NestFactory.create(AppModule, { logger: false, rawBody: true })
    await app.listen(0, "127.0.0.1")
    const payload = JSON.stringify({ event: "paid", amount: 5000 })
    const res = await fetch((await app.getUrl()) + "/webhook", { method: "POST", headers: { "Content-Type": "application/json" }, body: payload })
    console.log("POST /webhook →", res.status, await res.text())
    await app.close()
}
main()

