@Controller("cats")
export class CatsController {
    @Get()          list() { return [{ id: 1, name: "Mosh" }] }      // 200, application/json
    @Get(":id")     one() { return { id: 1, name: "Mosh" } }          // 200, {"id":1,"name":"Mosh"}
    @Get("count")   count() { return 3 }                              // 200, tana: 3      (text/html)
    @Get("name")    name() { return "Mosh" }                          // 200, tana: Mosh   (text/html)
    @Post()         create() { return { id: 2 } }                     // 201 — POST uchun sukut
    @Delete(":id")  remove() {}                                       // 200, bo'sh tana
    @Get("slow")    async slow() { return this.catsService.findAll() }   // Promise — kutiladi
}

@Post("login")
@HttpCode(200)                       // POST uchun 201 o'rniga 200 — login yaratish emas
login() { return { token: "..." } }

@Delete(":id")
@HttpCode(HttpStatus.NO_CONTENT)     // 204 — tanasiz javob
remove() {}

@Post("jobs")
@HttpCode(HttpStatus.ACCEPTED)       // 202 — qabul qilindi, keyin bajariladi
enqueue() { return { queued: true } }

@Get("docs")
@Redirect("https://docs.nestjs.com", 301)     // statik: doim shu manzil
docs() {}

@Get("go")
@Redirect("/", 302)                           // sukut — handler bekor qilishi mumkin
go(@Query("to") to?: string): HttpRedirectResponse | void {
    if (to === "shop") return { url: "/shop", statusCode: 301 }   // dinamik
}

import type { Response } from "express"

@Get("full")
full(@Res() res: Response) {                         // to'liq rejim: javobni O'ZINGIZ yuborasiz
    res.status(202).set("X-Queue", "a").json({ queued: true })
}                                                     // return qiymati e'tiborga olinmaydi

@Get("partial")
partial(@Res({ passthrough: true }) res: Response) { // passthrough: faqat sozlaysiz, yuborishni Nest qiladi
    res.status(201).setHeader("X-Total-Count", "42")
    return { ok: true }                               // tana — Nest orqali, interceptor'lar ishlaydi
}

@Get("promise")
async promise() {                      // Promise — Nest kutadi
    const cats = await this.catsService.findAll()
    return cats
}

@Get("observable")
observable() {                         // Observable — obuna bo'lib OXIRGI qiymatni yuboradi
    return of(1, 2, 3)                 // tana: 3
}

// ✘ @Res to'liq rejim + return — javob yuborilmaydi, so'rov osilib qoladi
@Get() bad(@Res() res: Response) { return { ok: true } }

// ✔ passthrough — statusni siz, tanani Nest
@Get() good(@Res({ passthrough: true }) res: Response) { res.status(202); return { ok: true } }

// ✘ xato uchun qo'lda javob:  res.status(404).json({ ... })
// ✔ exception — filter 404 JSON yasaydi
throw new NotFoundException("Topilmadi")

